"""一次性本地配置中心的静态页面。"""
from __future__ import annotations

import json
from typing import Any


def build_config_page(config: dict[str, Any]) -> str:
    state = json.dumps(config, ensure_ascii=False).replace("</", "<\\/")
    page = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AgentRelay 配置中心</title>
<style>
:root{--ink:#17212d;--muted:#647182;--paper:#ffffff;--canvas:#f3f6f8;--line:#dce4e8;--mint:#0c9b79;--coral:#e85c45;--sky:#0c6cc7;--shadow:0 18px 42px rgba(23,33,45,.08)}
*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:15px/1.55 -apple-system,BlinkMacSystemFont,"SF Pro Display","Segoe UI",sans-serif}
.app{max-width:1240px;margin:auto;padding:34px 24px 76px}.mast{display:flex;align-items:end;justify-content:space-between;gap:20px;margin:10px 0 30px;animation:enter .55s ease both}.brand{font-size:32px;font-weight:730;letter-spacing:0}.brand small{display:block;font-size:13px;font-weight:500;color:var(--muted);margin-top:5px}.mode{border:1px solid var(--line);background:var(--paper);padding:7px 11px;border-radius:7px;font-size:13px;color:var(--muted)}
.layout{display:grid;grid-template-columns:215px minmax(0,1fr);gap:28px}.nav{position:sticky;top:20px;align-self:start}.nav button{display:block;width:100%;border:0;background:transparent;text-align:left;padding:10px 12px;margin:2px 0;border-radius:7px;color:var(--muted);font:inherit;cursor:pointer;transition:background .18s,color .18s,transform .18s}.nav button:hover{background:#e8f0f0;color:var(--ink);transform:translateX(2px)}.nav button.active{background:var(--ink);color:#fff}.view{display:none}.view.active{display:block;animation:enter .42s ease both}.head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:16px}.head h1{font-size:24px;margin:0;letter-spacing:0}.hint{margin:4px 0 0;color:var(--muted);font-size:13px}.card{background:var(--paper);border:1px solid var(--line);border-radius:8px;padding:20px;box-shadow:var(--shadow);animation:rise .45s ease both}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.stat{font-size:30px;font-weight:700;margin-top:5px}.label{font-size:13px;color:var(--muted)}.stack{display:grid;gap:12px}.provider{display:flex;justify-content:space-between;align-items:center;gap:18px}.provider strong{display:block}.meta{font-size:13px;color:var(--muted);max-width:540px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.state{font-size:12px;margin-top:6px;color:var(--muted)}.state b{color:var(--mint)}.state .wait{color:#b16b00}.actions,.toolbar{display:flex;gap:8px;flex-wrap:wrap}.btn{appearance:none;border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:7px;padding:8px 12px;font:inherit;font-size:13px;cursor:pointer;transition:transform .18s,border-color .18s,background .18s}.btn:hover{transform:translateY(-1px);border-color:#9fb0b7}.btn.primary{border-color:var(--sky);background:var(--sky);color:#fff}.btn.danger{color:#b7372a}.empty{padding:26px;border:1px dashed #b9c6ca;border-radius:8px;color:var(--muted);text-align:center}.form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.field{display:flex;flex-direction:column;gap:6px}.field.full{grid-column:1/-1}.field label{font-size:13px;font-weight:600}.field input,.field select{width:100%;border:1px solid var(--line);background:#fff;border-radius:7px;padding:10px;color:var(--ink);font:inherit;outline:0}.field input:focus,.field select:focus{border-color:var(--sky);box-shadow:0 0 0 3px #0c6cc71a}.switch-row{display:flex;align-items:center;justify-content:space-between;gap:12px;border:1px solid var(--line);border-radius:7px;padding:11px 12px}.switch-row small{display:block;color:var(--muted);font-size:12px}.switch{width:42px;height:24px;position:relative;flex:0 0 auto}.switch input{opacity:0;width:0;height:0}.slider{position:absolute;inset:0;background:#b7c2c7;border-radius:99px;cursor:pointer;transition:.18s}.slider:before{content:"";width:18px;height:18px;position:absolute;left:3px;top:3px;background:#fff;border-radius:50%;transition:.18s;box-shadow:0 1px 3px #0003}.switch input:checked+.slider{background:var(--mint)}.switch input:checked+.slider:before{transform:translateX(18px)}.switch input:disabled+.slider{opacity:.45;cursor:not-allowed}.notice{border-left:3px solid var(--sky);padding:10px 12px;background:#edf5fc;color:#33495c;font-size:13px;margin:14px 0}.notice.warn{border-color:#d58917;background:#fff7e8}.check-result{margin-top:14px;font-size:13px;line-height:1.8}.toast{position:fixed;right:22px;bottom:22px;max-width:min(430px,calc(100vw - 44px));padding:12px 15px;background:var(--ink);border-radius:7px;color:#fff;opacity:0;transform:translateY(12px);transition:.22s;pointer-events:none;box-shadow:var(--shadow)}.toast.show{opacity:1;transform:none}.login-state{font-size:13px;color:var(--muted);margin-top:10px}.login-state.ok{color:var(--mint)}
@keyframes enter{from{opacity:0}to{opacity:1}}@keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}@media(max-width:780px){.app{padding:20px 14px 50px}.mast{align-items:start;flex-direction:column}.layout{display:block}.nav{position:static;display:flex;overflow:auto;gap:5px;margin-bottom:18px}.nav button{width:auto;white-space:nowrap}.grid,.form{grid-template-columns:1fr}.field.full{grid-column:auto}.provider{align-items:start;flex-direction:column}.head{align-items:start;flex-direction:column}}
</style></head><body><main class="app"><header class="mast"><div class="brand">AgentRelay<small>本机 Provider 配置中心</small></div><span class="mode" id="mode">离线基础模式</span></header><div class="layout"><nav class="nav"><button class="active" data-tab="overview">总览</button><button data-tab="commander">Commander</button><button data-tab="web">线上模型</button><button data-tab="local">本地模型</button><button data-tab="api">API 模型</button><button data-tab="security">安全与配置</button></nav><section>
<div id="overview" class="view active"><div class="head"><div><h1>当前状态</h1><p class="hint">环境检查确认安装链路；Provider 检查确认模型配置和登录状态。</p></div><div class="toolbar"><button class="btn" onclick="checkEnvironment()">检查环境</button><button class="btn" onclick="initializeFiles()">初始化基础文件</button><button class="btn primary" onclick="closeApp()">完成并关闭</button></div></div><div class="grid" id="stats"></div><div class="card" style="margin-top:14px"><strong>Provider 管理</strong><p class="hint">网页模型能否实际自动对话，取决于是否已接入该网站的操作规则。</p><div class="stack" id="overview-list" style="margin-top:15px"></div><div id="environment" class="check-result"></div></div></div>
<div id="commander" class="view"><div class="head"><div><h1>Commander</h1><p class="hint">主 Agent 按任务实际需要启动 1 到 5 个隔离子 Agent。</p></div><button class="btn primary" onclick="saveCommander()">保存</button></div><div class="card"><div class="form"><div class="field full"><div class="switch-row"><div><label>启用审查官模式</label><small id="commander-note">至少需要一个线上或本地模型。</small></div><label class="switch"><input id="commander-enabled" type="checkbox"><span class="slider"></span></label></div></div><div class="field full"><label>Codex 终端路径</label><input id="terminal-path" placeholder="codex 或 /路径/codex"></div><div class="field"><label>最多可启动的 Agent</label><select id="max-agents"><option value="1">1 个</option><option value="2">2 个</option><option value="3">3 个</option><option value="4">4 个</option><option value="5">5 个</option></select><p class="hint">这是上限；实际数量由主 Agent 按业务自动决定。</p></div></div><div class="notice">配置任意线上网页模型或本地模型后，Commander 会自动启用。API 模型只允许主 Agent 使用，不会交给子 Agent。</div></div></div>
<div id="web" class="view"><div class="head"><div><h1>线上网页模型</h1><p class="hint">登录状态加密保存在本机。DeepSeek 已可自动对话；其他网页先完成配置和登录，接入操作规则后才可自动对话。</p></div><button class="btn primary" onclick="showForm('web')">新增线上模型</button></div><div class="stack" id="web-list"></div><div id="web-form" style="margin-top:14px"></div></div>
<div id="local" class="view"><div class="head"><div><h1>本地模型</h1><p class="hint">支持 Ollama、LM Studio、vLLM、llama.cpp 的 OpenAI 兼容服务。</p></div><div class="toolbar"><button class="btn" onclick="scanLocal()">扫描本机服务</button><button class="btn primary" onclick="showForm('local')">新增本地模型</button></div></div><div id="local-scan" class="notice" style="display:none"></div><div class="stack" id="local-list"></div><div id="local-form" style="margin-top:14px"></div></div>
<div id="api" class="view"><div class="head"><div><h1>API 模型</h1><p class="hint">密钥不会在页面回显，只加密保存在本机。</p></div><button class="btn primary" onclick="showForm('api')">新增 API 模型</button></div><div class="stack" id="api-list"></div><div id="api-form" style="margin-top:14px"></div></div>
<div id="security" class="view"><div class="head"><div><h1>安全与配置</h1><p class="hint">Cookie、登录状态和 API Key 均不显示在页面中。</p></div></div><div class="card"><p>统一配置文件：<code id="config-path"></code></p><p>登录状态和配置由本机密钥加密，页面只监听 127.0.0.1。</p><button class="btn primary" onclick="closeApp()">保存并关闭</button></div></div>
</section></div></main><div class="toast" id="toast"></div><script>
const state=__CONFIG__;const $=id=>document.getElementById(id);let loginPoll=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3300)}
async function api(path,options={}){const response=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const data=await response.json();if(!response.ok)throw Error(data.error||'请求失败');return data}
function titleStem(alias){const known={deepseek:'DeepSeek',qianwen:'Qianwen',kimi:'Kimi'};const clean=String(alias||'Model').trim().replace(/-web$/i,'');return clean.split(/[-_\s]+/).filter(Boolean).map(x=>known[x.toLowerCase()]||x.charAt(0).toUpperCase()+x.slice(1)).join('')||'Model'}
function autoTitles(alias){const root='AgentRelay-'+titleStem(alias);return {flash:root+'-Flash',expert:root+'-Expert'}}
function providers(kind){return state[kind+'_providers']||[]}
function available(){return providers('web').some(p=>p.enabled!==false)||providers('local').some(p=>p.enabled!==false)}
function providerStatus(kind,p){if(kind==='web'){if(p.adapter==='deepseek')return '<b>DeepSeek 已接通</b>：专属适配器，可自动发送问题并读取回复';if(p.adapter==='generic')return '<b>通用兜底适配器</b>：会尝试自动对话；个别网站不稳定时可再补专属适配器';return '<span class="wait">已保存网页登录配置</span>：目前还不能自动操作这个网站的对话页面'}if(kind==='local')return '<b>本地单并发</b>：一次只服务一个 Agent，其他请求按队列等待';return '<b>仅主 Agent</b>：Commander 子 Agent 不会调用 API'}
function card(kind,p,actions=true){return `<article class="card provider"><div><strong>${esc(p.name||p.id)} ${p.id===state.default_provider?'· 默认':''}</strong><div class="meta">${esc(p.id)} · ${esc(p.base_url||p.endpoint||'')}</div><div class="state">${providerStatus(kind,p)} · ${p.enabled!==false?'已启用':'已停用'}</div></div>${actions?`<div class="actions"><button class="btn" onclick="testProvider('${kind}','${esc(p.id)}')">测试</button><button class="btn" onclick="showForm('${kind}','${esc(p.id)}')">编辑</button><button class="btn" onclick="toggleProvider('${kind}','${esc(p.id)}')">${p.enabled!==false?'停用':'启用'}</button>${kind==='web'?`<button class="btn" onclick="setDefault('${esc(p.id)}')">设为默认</button>`:''}<button class="btn danger" onclick="deleteProvider('${kind}','${esc(p.id)}')">删除</button></div>`:''}</article>`}
function render(){const c=state.commander||{};$('mode').textContent=c.enabled?'Commander 已启用':'离线基础模式';$('config-path').textContent=state.config_path||'本机加密目录';const ok=available();$('commander-enabled').checked=!!c.enabled;$('commander-enabled').disabled=!ok;$('commander-note').textContent=ok?'已检测到线上或本地模型，默认启用；可手动关闭。':'尚未配置线上或本地模型，暂时无法开启。';$('terminal-path').value=c.terminal_path||c.terminal||'codex';$('max-agents').value=c.max_agents||5;const types=[['线上模型',providers('web').length],['本地模型',providers('local').length],['API 模型',providers('api').length]];$('stats').innerHTML=types.map(([name,count])=>`<div class="card"><div class="label">${name}</div><div class="stat">${count}</div></div>`).join('');const list=[['web',providers('web')],['local',providers('local')],['api',providers('api')]].flatMap(([kind,items])=>items.map(p=>card(kind,p,false)));$('overview-list').innerHTML=list.join('')||'<div class="empty">还没有 Provider，离线基础能力仍可使用。</div>';['web','local','api'].forEach(kind=>$(kind+'-list').innerHTML=providers(kind).map(p=>card(kind,p)).join('')||'<div class="empty">暂无配置。</div>')}
document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-tab],.view').forEach(el=>el.classList.remove('active'));button.classList.add('active');$(button.dataset.tab).classList.add('active')});
function switchRow(id,title,detail,checked){return `<div class="switch-row"><div><label>${title}</label><small>${detail}</small></div><label class="switch"><input id="${id}" type="checkbox" ${checked?'checked':''} onchange="updateModes()"><span class="slider"></span></label></div>`}
function updateModes(){const mixed=$('f-hybrid')?.checked;if(mixed){$('f-flash').checked=true;$('f-expert').checked=true}$('f-flash').disabled=!!mixed;$('f-expert').disabled=!!mixed;[['flash','f-flash-title'],['expert','f-expert-title']].forEach(([mode,id])=>{const node=$(id);if(node)node.closest('.field').style.display=(mixed||$('f-'+mode).checked)?'flex':'none'})}
function setAutoTitles(){const titles=autoTitles($('f-id').value);[['flash','f-flash-title'],['expert','f-expert-title']].forEach(([mode,id])=>{const field=$(id);if(field&&(field.dataset.auto==='true'||!field.value)){field.value=titles[mode];field.dataset.auto='true'}})}
function titleEdited(id){$(id).dataset.auto='false'}
function showForm(kind,id=''){const p=providers(kind).find(x=>x.id===id)||{};const c=p.conversation||{};const newItem=!id;const names=autoTitles(p.id);let html='';if(kind==='web'){html=`<div class="card"><h2>${id?'编辑':'新增'}线上模型</h2><div class="form"><div class="field"><label>别名</label><input id="f-id" value="${esc(p.id)}" placeholder="qianwen" oninput="setAutoTitles()"></div><div class="field"><label>显示名称</label><input id="f-name" value="${esc(p.name)}" placeholder="千问线上"></div><div class="field full"><label>对话页面网址</label><input id="f-url" value="${esc(p.base_url||p.url)}" placeholder="https://www.qianwen.com/"></div><div class="field full">${switchRow('f-flash','极速模式','使用极速会话',c.supports_flash??(p.id==='deepseek-web'))}${switchRow('f-expert','专家模式','使用专家会话',c.supports_expert??(p.id==='deepseek-web'))}${switchRow('f-hybrid','混合模式','同时使用极速和专家两套会话',c.supports_hybrid??(p.id==='deepseek-web'))}${switchRow('f-images','支持图片','这是所有模式共用的能力',!!c.supports_images)}</div><div class="field"><label>极速会话名称</label><input id="f-flash-title" data-auto="${newItem?'true':'false'}" oninput="titleEdited('f-flash-title')" value="${esc(c.titles?.flash||names.flash)}"></div><div class="field"><label>专家会话名称</label><input id="f-expert-title" data-auto="${newItem?'true':'false'}" oninput="titleEdited('f-expert-title')" value="${esc(c.titles?.expert||names.expert)}"></div></div><div class="notice">没有对应会话时，AgentRelay 会自动创建。混合模式只使用极速和专家两套会话。</div><div class="toolbar"><button class="btn" onclick="startWebLogin()">打开网页登录</button><button class="btn primary" onclick="saveProvider('web')">保存配置</button><button class="btn" onclick="$('web-form').innerHTML=''">取消</button></div><div class="login-state" id="login-state"></div></div>`}else if(kind==='local'){html=`<div class="card"><h2>${id?'编辑':'新增'}本地模型</h2><div class="form"><div class="field"><label>别名</label><input id="f-id" value="${esc(p.id)}" placeholder="llama-local"></div><div class="field"><label>显示名称</label><input id="f-name" value="${esc(p.name)}" placeholder="我的 llama.cpp"></div><div class="field full"><label>接口地址</label><input id="f-endpoint" value="${esc(p.endpoint)}" placeholder="http://127.0.0.1:8080/v1"></div><div class="field"><label>模型名称</label><input id="f-model" value="${esc(p.model)}" placeholder="模型名称"></div><div class="field"><label>排队等待上限（秒）</label><input id="f-timeout" type="number" min="1" value="${p.queue_timeout||30}"><p class="hint">本地模型正忙时，其他 Agent 最多等待多久；超时才会尝试线上模型或继续离线处理。</p></div></div><div class="toolbar"><button class="btn primary" onclick="saveProvider('local')">保存配置</button><button class="btn" onclick="$('local-form').innerHTML=''">取消</button></div></div>`}else{html=`<div class="card"><h2>${id?'编辑':'新增'}API 模型</h2><div class="form"><div class="field"><label>别名</label><input id="f-id" value="${esc(p.id)}" placeholder="my-api"></div><div class="field"><label>显示名称</label><input id="f-name" value="${esc(p.name)}" placeholder="我的 API 模型"></div><div class="field full"><label>API 地址</label><input id="f-endpoint" value="${esc(p.endpoint)}" placeholder="https://api.example/v1"></div><div class="field"><label>模型名称</label><input id="f-model" value="${esc(p.model)}" placeholder="模型名称"></div><div class="field"><label>请求类型</label><select id="f-type"><option value="openai-compatible">OpenAI 兼容聊天</option><option value="custom-compatible">自定义兼容接口</option></div><div class="field full"><label>API Key（编辑时留空即保留旧值）</label><input id="f-key" type="password"></div></div><div class="toolbar"><button class="btn" onclick="testApiForm()">测试接口</button><button class="btn primary" onclick="saveProvider('api')">保存配置</button><button class="btn" onclick="$('api-form').innerHTML=''">取消</button></div></div>`}$((kind)+'-form').innerHTML=html;if(kind==='web'){setAutoTitles();updateModes()}if(kind==='api'&&p.request_type)$('f-type').value=p.request_type}
async function saveProvider(kind){try{const p={id:$('f-id').value.trim(),name:$('f-name').value.trim(),enabled:true};if(kind==='web'){const hybrid=$('f-hybrid').checked;p.base_url=$('f-url').value.trim();p.conversation={supports_flash:$('f-flash').checked||hybrid,supports_expert:$('f-expert').checked||hybrid,supports_hybrid:hybrid,supports_images:$('f-images').checked,create_if_missing:true,titles:{flash:$('f-flash-title').value.trim(),expert:$('f-expert-title').value.trim(),hybrid:'AgentRelay-'+titleStem($('f-id').value)}}}else{p.endpoint=$('f-endpoint').value.trim();p.model=$('f-model').value.trim()}if(kind==='local')p.queue_timeout=Number($('f-timeout').value)||30;if(kind==='api'){p.api_key=$('f-key').value;p.request_type=$('f-type').value}const data=await api('/api/providers',{method:'POST',body:JSON.stringify({kind,provider:p})});Object.assign(state,data.config);render();toast('配置已加密保存')}catch(error){toast(error.message)}}
async function startWebLogin(){try{const hybrid=$('f-hybrid').checked;const p={id:$('f-id').value.trim(),name:$('f-name').value.trim(),base_url:$('f-url').value.trim(),conversation:{supports_flash:$('f-flash').checked||hybrid,supports_expert:$('f-expert').checked||hybrid,supports_hybrid:hybrid,supports_images:$('f-images').checked,create_if_missing:true,titles:{flash:$('f-flash-title').value.trim(),expert:$('f-expert-title').value.trim(),hybrid:'AgentRelay-'+titleStem($('f-id').value)}}};const data=await api('/api/login',{method:'POST',body:JSON.stringify({provider:p})});Object.assign(state,data.config);$('login-state').textContent='浏览器已打开。登录完成后关闭这个对话标签页，页面会自动提示已保存。';watchLogin(p.id);toast('网页登录窗口已打开')}catch(error){toast(error.message)}}
function watchLogin(id){clearInterval(loginPoll);loginPoll=setInterval(async()=>{try{const data=await api('/api/login-status?id='+encodeURIComponent(id));const node=$('login-state');if(data.saved){clearInterval(loginPoll);if(node){node.textContent='登录状态已加密保存，可以继续配置或关闭页面。';node.classList.add('ok')}toast('登录状态已保存')}else if(node)node.textContent='正在等待你登录并关闭对话标签页…'}catch(_){clearInterval(loginPoll)}},1800)}
async function saveCommander(){try{const enabled=$('commander-enabled').checked;const data=await api('/api/settings',{method:'POST',body:JSON.stringify({commander:{enabled,manual_disabled:!enabled,terminal_path:$('terminal-path').value.trim(),max_agents:Number($('max-agents').value)||5}})});Object.assign(state,data.config);render();toast('Commander 配置已保存')}catch(error){toast(error.message)}}
async function toggleProvider(kind,id){try{const data=await api('/api/providers/action',{method:'POST',body:JSON.stringify({kind,id,action:'toggle'})});Object.assign(state,data.config);render()}catch(error){toast(error.message)}}async function setDefault(id){try{const data=await api('/api/providers/action',{method:'POST',body:JSON.stringify({kind:'web',id,action:'default'})});Object.assign(state,data.config);render();toast('默认网页模型已更新')}catch(error){toast(error.message)}}async function deleteProvider(kind,id){if(!confirm('确定删除这个 Provider？'))return;try{const data=await api('/api/providers?kind='+kind+'&id='+encodeURIComponent(id),{method:'DELETE'});Object.assign(state,data.config);render()}catch(error){toast(error.message)}}
async function testProvider(kind,id){try{const data=await api('/api/test',{method:'POST',body:JSON.stringify({kind,id})});toast(data.message)}catch(error){toast(error.message)}}async function testApiForm(){try{const data=await api('/api/test',{method:'POST',body:JSON.stringify({kind:'api',endpoint:$('f-endpoint').value,model:$('f-model').value,api_key:$('f-key').value})});toast(data.message)}catch(error){toast(error.message)}}
async function scanLocal(){try{const data=await api('/api/scan-local');const box=$('local-scan');box.style.display='block';box.innerHTML=data.found.length?'检测到本地服务：'+data.found.map(x=>`<button class="btn" onclick="useLocal('${esc(x.endpoint)}','${esc(x.models[0]||'')}')">${esc(x.name)} · ${esc(x.endpoint)} · ${esc(x.models.join('、')||'未返回模型')}</button>`).join(' '):'没有发现 Ollama、LM Studio、vLLM 或 llama.cpp。llama.cpp 默认常见端口为 8080；请确认它启动了 OpenAI 兼容服务器（/v1/models）。';toast(data.found.length?'扫描完成':'未发现兼容本地服务')}catch(error){toast(error.message)}}function useLocal(endpoint,model){showForm('local');$('f-endpoint').value=endpoint;$('f-model').value=model}
async function checkEnvironment(){try{const data=await api('/api/environment');const fail=data.checks.filter(x=>!x.ok);$('environment').innerHTML='<strong>环境检查检查的是安装链路，不检查模型登录。</strong><br>'+data.checks.map(x=>`${x.ok?'✓':'!'} ${esc(x.name)}：${esc(x.detail)}（${esc(x.reason)}）`).join('<br>');toast(fail.length?'未找到：'+fail.map(x=>x.name).join('、'):'环境检查通过')}catch(error){toast(error.message)}}async function initializeFiles(){try{const data=await api('/api/initialize',{method:'POST'});toast(data.message)}catch(error){toast(error.message)}}async function closeApp(){try{await api('/api/close',{method:'POST'});document.body.innerHTML='<main class="app"><div class="card"><h1>配置已完成</h1><p>本地配置服务已关闭，可以安全关闭这个页面。</p></div></main>'}catch(error){toast(error.message)}}render();
</script></body></html>"""
    return page.replace("__CONFIG__", state)
